import{_ as o,o as u,c as q,ag as r}from"./chunks/framework.D5hoimZQ.js";const i=JSON.parse('{"title":"03 货币蓄水池与债务周期（知识手册）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/handbook/03_货币蓄水池与债务周期.md","filePath":"topics/tianya/handbook/03_货币蓄水池与债务周期.md"}'),n={name:"topics/tianya/handbook/03_货币蓄水池与债务周期.md"};function s(g,t,a,d,p,e){return u(),q("div",null,[...t[0]||(t[0]=[r('<h1 id="_03-货币蓄水池与债务周期-知识手册" tabindex="-1">03 货币蓄水池与债务周期（知识手册） <a class="header-anchor" href="#_03-货币蓄水池与债务周期-知识手册" aria-label="Permalink to &quot;03 货币蓄水池与债务周期（知识手册）&quot;">​</a></h1><blockquote><p>来源：天涯经济帖核心框架的体系化重述，材料取自 flp713《冰冷的经济真相》〔16〕、第三元《2013-2017的大框架》〔9〕、kulese《戏说牛市合适崩盘》〔15〕、七剑战歌之风月〔20〕、海边的老王《赚未来十年的钱》〔23〕、大文豪曼因斯坦〔43〕、yyttff1981〔84〕、黄汉升〔92〕、螺蛳及顶伟大少〔175〕、不要二分法〔176〕。方括号为帖号。所有数字均出自帖内原文。</p></blockquote><h2 id="一、货币蓄水池论-超发货币的完整去向链" tabindex="-1">一、货币蓄水池论：超发货币的完整去向链 <a class="header-anchor" href="#一、货币蓄水池论-超发货币的完整去向链" aria-label="Permalink to &quot;一、货币蓄水池论：超发货币的完整去向链&quot;">​</a></h2><p><strong>原理</strong>：汇率管制+出口导向下，中国每一美元顺差都变成一笔被动投放的基础货币。1992–1994 年 M2 增速 31.3%、37.3%、34.5%，因无池可蓄，1994 年直接变成约 25% 的通胀——这是&quot;蓄水池&quot;理论的原始实验〔16〕。2010 年 GDP 约 40 万亿而 M2 已 70 万亿，&quot;每创造 1 元财富，央行发行 1.8 元人民币&quot;〔16〕。超发的钱不进物价，就必须有池子。</p><p><strong>蓄水池的三个条件</strong>：容量足够大（几十万亿级）；资金进去后沉淀不动（不冲击 CPI）；对管理层有额外用途（融资、财政、稳定）。满足三条的只有三个候选：股市、房市、土地。</p><p><strong>历次换池（时间表+条件+受益受损）</strong></p><table tabindex="0"><thead><tr><th>阶段</th><th>池子</th><th>启动条件</th><th>时点标志</th><th>受益方</th><th>代价方</th></tr></thead><tbody><tr><td>1994–2000</td><td>民生市场化（教育、医疗、住房）</td><td>分税制后地方变吃饭财政，必须把支出甩给居民</td><td>1998 取消福利分房+按揭启动</td><td>财政、后来入场的资本</td><td>居民（看不起病上不起学买不起房）</td></tr><tr><td>2000–2011</td><td>股市+房市</td><td>2003 年住建部文件用&quot;带保障性质的商品房&quot;替代经济适用房，拆掉房改的保险</td><td>2005–2007 股市 998→6124；房价三倍</td><td>中央（国企脱困）、地方（卖地）、银行</td><td>2007–08 股民（市值蒸发超 20 万亿）〔16〕</td></tr><tr><td>2011–2020（设计）</td><td>短期：房市+股市；中期：股市+土地（土改确权）；长期：人民币国际化</td><td>三大改革＝股改、汇改、土改〔16〕</td><td>2014 IPO 放量、2015 牛市</td><td>按第三元的博弈分析：权贵资本高位脱手</td><td>被锁在高位的民间资本</td></tr><tr><td>2014–2015</td><td>股市（换池尝试）</td><td>央行行长 2011 年暗示&quot;造新的蓄水池&quot;；&quot;IPO 发行之日，就是蓄水池正式启动之时&quot;〔9〕</td><td>2014.11 券商行情→2015.6 顶</td><td>大资金（4500 点前离场者）</td><td>配资散户、中产</td></tr><tr><td>2016</td><td>房市（回流）</td><td>股灾后股市吸储失败，外储告急</td><td>2016 一线翻倍</td><td>先行套现者、地方财政</td><td>全体杠杆购房者</td></tr></tbody></table><p><strong>股市与房市的功能差异（关键知识）</strong>：股市是&quot;蓄水池+锅&quot;——可以扩容吸储，也可以崩盘蒸发财富、消灭购买力抑制通胀，2007 年 5 月猪肉破 20 元与 5.30 暴跌时间重合，&quot;在你生活压力最大的时候，股票只能割肉&quot;〔16〕。房市只能是蓄水池、不能是锅：房子有使用价值、遍地有抵押物，除非经济整体崩盘，不会出现股市式的无量暴跌；&quot;用股市类比楼市一定会出错&quot;〔16〕。反过来，金融属性越强的资产，跌时越无人接手——商铺先于住宅破，&quot;一铺养三代&quot;先变没人要〔43〕。</p><p><strong>换池的传导次序（第三元的方法论）</strong>〔9〕：全球贬值接力日元→英镑→欧元→澳元→人民币（人民币最后贬）；&quot;当央行降息之时就是人民币贬值的上半阶段&quot;，贬值上半场对应股市慢牛、地产未死；&quot;澳元开始贬值、欧元开始贬值的时候，才是地产人民币反转的时候&quot;。用汇率-利率-资产的先后次序定位自己所处的池子阶段。</p><p><strong>&quot;长期池&quot;的蓝图与局限（flp713 的土改大棋局）</strong>〔16〕：土地确权→流转、集约、抵押、买卖八字方针；扩权强县把低附加值产业迁往中小城市吸纳进城农民；村镇银行（小贷公司转制）提供配套金融。flp713 的推演是牵一发动全身：确权创造 2.4 亿亩宅基地对应的数十万亿财富蓄水池、启动内需、稳定地价房价、顺带解决春运与户口。配套的另一个&quot;关键子&quot;是转基因种子——没有大规模粮食稳产托底，土地流转就不敢推进。<strong>这套设计的局限</strong>：它假设农民进城意愿与城市购房力持续存在，即蓄水池的分母端（人口与收入）永远增长；这一假设在 2020 年后失效。人民币国际化的路径判断则是清醒的：&quot;伦敦纽约成为国际金融中心用了 200 年，而管理层要用 10 年把上海建成国际金融中心&quot;——flp713 把这份 2009 年文件类比为&quot;3 年赶英超美&quot;式的心态，结论是白送别人都不要，国际化&quot;很难很难&quot;。</p><p><strong>换池失败的判据</strong>：① 池子锁死的流动性无法兑现——想卖的人卖不出，流动性枯竭等于池子失效；② 锁住的不是财富是负债——杠杆购房者同时丧失换汇能力与消费能力，池子反噬内需；③ 新池子容量不足——股市 2015 年接不住楼市的体量（A 股流通市值远小于房产存量），注册制推了八年才落地〔15〕预测的&quot;跌到底换制度&quot;直到 2023 年才兑现；④ 判断池子真假最简单的现场测试〔43〕：金融属性资产一旦跌价没有任何人接手，&quot;直到跌回他本来的居住价值属性&quot;——商铺是先行样本。</p><p><strong>博弈结构（第三元对 4 万亿的解构）</strong>〔9〕：蓄水池里鱼龙混杂——国家队、权贵资本、有背景外资、民间资本。2008 年暴跌把所有人套住后，四万亿&quot;通过疯狂拉抬地产基建，让有背景的资金相对高位脱手，让民间资本和弱势群体接盘泡沫资产&quot;，辅助手段是通胀与负利率逼弱势资金入场。任何一次&quot;换池&quot;都要问：谁在高位，谁被动员进场。</p><h2 id="二、外储之锚模型-外储是因-房产是果" tabindex="-1">二、外储之锚模型：&quot;外储是因，房产是果&quot; <a class="header-anchor" href="#二、外储之锚模型-外储是因-房产是果" aria-label="Permalink to &quot;二、外储之锚模型：&quot;外储是因，房产是果&quot;&quot;">​</a></h2><p><strong>基础货币的构成（2016 年数据）</strong>〔43〕：央行资产负债表&quot;储备货币&quot;约 29 万亿＝外汇占款 23.5 万亿＋本币投放 5 万亿。29 万亿基础货币经银行放贷-回存循环放大到 149 万亿 M2，&quot;一块变五块&quot;就是货币乘数；准备金率只是上限，&quot;贷不贷是下头（商业银行）决定&quot;。所以人民币的锚在法律事实上是美元：外汇占款占基础货币八成。</p><p><strong>完整因果链</strong>：贸易顺差+外资流入→央行购汇→基础货币投放→乘数放大→M2 高速增长（07 年准备金率 9% 一路加到 12 年 21% 仍挡不住）→资产价格上涨；2014 年外汇占款见顶 29 万亿后逆转：每流失 1 美元注销 6 元多人民币，&quot;外汇占款每下降一千亿，乘以乘数就是五千亿的缺口&quot;〔43〕→国内流动性被动收缩→降准只是对冲不是放水。</p><p><strong>为什么外储是命门</strong>：中国每年进口几千亿美元石油，三分之一粮食靠进口，饲料-肉蛋转化率固定，&quot;手中有粮，心中不慌&quot;——楼市塌了可以咬牙还贷上黑名单，买不起石油和粮食不能〔43〕。这就是&quot;老大哥真正的命门是外储&quot;的全部逻辑：外储是生存问题，楼市是政治问题，政治问题可以让步，生存问题不能。</p><p><strong>2016 年锁游资的推演细节</strong>〔43〕：① 2015 年外储从 4 万亿跌到 3.2 万亿，人人换美元，&quot;外储一旦要爆也是爆在国内&quot;；② 2016 年初一线房价在无基本面变化下暴涨翻倍——传导周期对不上 1 月放水，只能是有形之手；③ 暴涨+杠杆+限售＝把社会游资全部锁进一线房产：&quot;你想换美元？你没钱了&quot;；④ 事实验证：外储 2016 年 2–3 月站稳 3.2 万亿左右，&quot;汇率虽然在节节败退，但他绝不是在溃败&quot;——贬值有序进行，弹药没有大量消耗；⑤ &quot;用一个生死问题去掩盖一个大问题&quot;，围棋弃大龙换实地。所有认为&quot;必须保楼市&quot;的人，前提就错了。</p><p><strong>贬值的管理学（高压锅模型）</strong>〔43〕：贬值对中国有利（释放资金压力、刺激出口），但&quot;不能太快，一旦跳贬……就像高压锅，缓慢释放有利，直接掀盖就炸&quot;，且会引发踩踏式资金出逃；中美在&quot;人民币不跳贬&quot;上有共同利益——美联储&quot;最理想的是人民币挺住，剪完羊毛就行，绝不是想要这羊带着人肉炸弹直奔家里来&quot;。因此看到的是有管理的贬值序列，而非一次性出清。<strong>条件</strong>：该模型成立的前提是资本项目未开放；一旦可自由兑换，锁游资失效，模型作废〔43〕。</p><p><strong>内外压力的转换律</strong>〔43〕：&quot;既然无法从外部解决，那一定会把内部的气压放掉&quot;——外储守住后，内部资产价格（楼市）承担全部调整压力。汇率与楼价是跷跷板：七剑的表述是&quot;现在这 M2，不加息汇率还能不能稳定……什么房地产就抛弃了，保命要紧&quot;〔20〕。</p><h2 id="三、从-印钞-通胀-到-债务-通缩-叙事切换的机制" tabindex="-1">三、从&quot;印钞-通胀&quot;到&quot;债务-通缩&quot;：叙事切换的机制 <a class="header-anchor" href="#三、从-印钞-通胀-到-债务-通缩-叙事切换的机制" aria-label="Permalink to &quot;三、从&quot;印钞-通胀&quot;到&quot;债务-通缩&quot;：叙事切换的机制&quot;">​</a></h2><p><strong>明斯基三阶段（识别庞氏）</strong>〔43〕：第一阶段企业偿本付息；第二阶段净利润只够还利息、本金滚贷；第三阶段连利息都靠不断拆借、夸大资产来延缓爆发——庞氏借贷。识别特征：<strong>借新钱是为了还旧债利息，而不是形成产能</strong>。2015 年 15.6 万亿社会融资&quot;至少一半多进入这个循环&quot;（彭博口径）。</p><p><strong>货币政策失效的机制</strong>〔43〕：长期放水→产能过剩+实业全面亏损→银行不敢放实业、实业不敢借钱→信贷在金融体系空转赌博，&quot;大家一起借钱去空对空&quot;；2016 年 7 月新增贷款 102% 是房贷——货币传导管道断了，&quot;连放水都拉不起物价&quot;。此时央行的每一次降准都不是制造通胀，而是&quot;弥补外汇占款流失&quot;的救火。</p><p><strong>为什么放水失效后是通缩而非通胀</strong>：三个约束叠加。① 产能过剩：做啥都不赚钱，放出去的信贷只会变坏账，&quot;每次价格回升都是假阳——价格上涨是去产能涨出来的，产能一恢复价格立马回落，每轮涨价绝对涨不过前期顶部&quot;；② 世界工厂约束：中国什么都能造，&quot;你涨价？太好了，哥们上，马上做得没利润&quot;，供给弹性封死物价上限；③ 外储约束：恶性通胀的唯一触发条件是&quot;外储耗尽、进出口停滞、钱失去锚点&quot;——委内瑞拉式，中国只要还是世界工厂就不会〔43〕。</p><p><strong>去杠杆的三条路径（帖内素材归纳）</strong>：① <strong>紧缩刺破</strong>——&quot;接着放央行绝对不敢，再放下去银行有全面破产可能&quot;，但刺破债务没人敢担责，&quot;在中国一定是拖到没法解决了才有动作&quot;〔43〕；② <strong>通胀稀释</strong>——&quot;用通胀解决债务，这个不现实了……产能过剩，印钱不解决本质问题&quot;〔20〕，最理想的办法是税收慢慢化解；③ <strong>时间换空间（实际走的路）</strong>——&quot;这些天量债务，一部分政府打包低息置换慢慢还，一部分转嫁到其他人手里，就是房奴、借贷的人。现在还保有大量现金的人，是收到了虚假繁荣的好处又没负担成本的幸运儿&quot;〔43〕。三条路径的选择顺序：③ 优先，走不通才 ①，② 基本被产能过剩排除。</p><p><strong>通缩的自我强化环</strong>：收入预期下降→不敢消费→需求下降→价格与工资下降→债务的实际负担上升→更不敢消费。中国上次经历通缩是 90 年代末：&quot;上海房子一平 3000 送户口没人要——我得先吃饭。所有人拿到钱就收起来，这就是通缩&quot;〔43〕。通缩期的资产定价逻辑：金融属性资产无人接手，跌回居住/使用价值为止。</p><p><strong>两代通缩的差异（帖内对照）</strong>〔43〕：90 年代末的通缩里&quot;大多数人外债都少&quot;，苦在收入不稳；这一轮&quot;是在风暴中心&quot;，且全社会初次带着史无前例的居民负债进入下行——同样价格下跌，杀伤力完全不同，&quot;这波苦的就是乱上杠杆的；只要别有负债，日子不会和以前差太多，说不定还会更舒服&quot;。这是判断个体在通缩中受损程度的第一变量：<strong>净头寸（现金-负债），而不是收入</strong>。</p><p><strong>去产能与假阳性的识别</strong>〔43〕：2016 年供给侧去产能推起的价格被当时舆论解读为&quot;新周期复苏&quot;。帖内的判据：08 年涨价背后是真实的社会需求扩张，&quot;价格每次上涨都是真实的，能支撑产能上涨&quot;；2016 年涨价是行政去产能涨出来的，&quot;产能一恢复价格立马回落&quot;。可操作的识别法：<strong>看涨价能否吸引产能回来</strong>——能吸引并压回价格的上涨是真需求，一涨价就被供给打回的上涨是行政假阳；对应到资产，&quot;每轮涨价绝对涨不过前期顶部&quot;。</p><h2 id="四、崩盘时点为何集体早-3-年-路径依赖的知识" tabindex="-1">四、崩盘时点为何集体早 3 年：路径依赖的知识 <a class="header-anchor" href="#四、崩盘时点为何集体早-3-年-路径依赖的知识" aria-label="Permalink to &quot;四、崩盘时点为何集体早 3 年：路径依赖的知识&quot;">​</a></h2><p><strong>样本</strong>：kulese 2015.5 预判股灾（对，两周后兑现）〔15〕；曼因斯坦 2016.10 预判 2017 年楼市全面着陆（实际顶部 2021）〔43〕；七剑 2018.3 预判当年崩至 2015 年价位（实际 2021 后才普跌）〔20〕；第三元 2013 预判 2016–2018 房价下跌（同上）〔9〕。方向全对，时点系统性提前 3 年左右。</p><p><strong>机制一：政策目标函数里&quot;拖&quot;是理性解</strong>。保增长=保就业=保稳定，&quot;货币蓄水池只能缓解通胀不能解决通胀，是治标——空间换时间&quot;〔16〕本身就是执政思路；工具箱里排序永远是：货币宽松→财政置换→展期→行政限价限售→最后一才是刺破。&quot;没有人敢承担刺破的责任&quot;〔43〕。帖作者把经济逻辑当政策时点，而政策的贴现率远低于市场。</p><p><strong>机制二：展期机器让风险不落地</strong>。钢贸案例〔175〕：2012 年初钢贸系统性崩盘本可&quot;一举拔除毒瘤&quot;，结果银行间达成回收再贷共识，&quot;钢贸撑过了二月二&quot;——&quot;风险不会凭空消失，经济更不会因为放水和转贷展期而起死回生&quot;，但展期能把爆点推迟数年。银行展期的动机：不展期=不良暴露=当期利润与帽子全没；展期=问题变成下一任的。微观激励决定了宏观出清被无限顺延。</p><p><strong>机制三：增长确实能稀释债务</strong>。2007 年股市蒸发 20 万亿，靠随后几年增长消化；1998、2008 两轮都靠&quot;增量&quot;翻篇。只要名义 GDP 增速高于利率，债务比率就不恶化——这给了&quot;拖&quot;以真实空间，直到 2015 年后名义增速跌破融资成本（第三元：&quot;今年也是 GDP 增加值不够债务利息的第一年&quot;，是争论中出现的数据化判据〔9〕）。</p><p><strong>机制四：政治日历约束</strong>。第三元：&quot;房价肯定在新任政府第二届任期之前搞定，这是中国的规则&quot;〔9〕——重大出清被安排在换届后的窗口，而不是经济触发的时点。反过来 kulese 对改革时点的推理同构：&quot;没有哪一次改革是在顺风顺水的时候开始并成功的，只有等大多数人都不好过了，才会支持变革&quot;〔15〕——政策要在民意成本最低的时点动刀，注册制选择在股灾之后推出、熔断之后再叫停，都是同一逻辑的展开。<strong>把&quot;经济该出清的时点&quot;换成&quot;政治能出清的时点&quot;，时点误差即可解释大半。</strong></p><p><strong>flp713 的&quot;调控必报复性上涨&quot;是同族知识</strong>〔16〕：调控只压制交易（限购）与信贷（限贷），不解决供地垄断与货币超发两个根因，&quot;面粉价格上去了，面包能不涨价吗&quot;——被压制的需求在放松后集中释放，2012–2013、2015–2016 两轮报复性上涨兑现。其反面教训在 2021 年后显形：当货币与供地两个根因同时逆转（人口下行+主动去杠杆），&quot;报复性上涨&quot;的循环才真正终结——<strong>周期框架的每一环都依赖其成立条件，条件消失则循环本身退出</strong>。</p><p><strong>修正律</strong>：这套框架的<strong>方向判断可用，时点判断要乘 2–3 年系数</strong>；触发器不是模型自己，而是外储流失速度、就业压力、财政能力这三个&quot;保的成本＞弃的成本&quot;的变量。曼因斯坦自己也写了免责声明式的判据：&quot;如果央行继续霜降（宽松），你就可以把他们当路边社报道&quot;——政策行为验证才是确认信号，预测只是假设〔43〕。</p><h2 id="五、银行基层运营-宏观数据失真的微观根源〔175〕" tabindex="-1">五、银行基层运营：宏观数据失真的微观根源〔175〕 <a class="header-anchor" href="#五、银行基层运营-宏观数据失真的微观根源〔175〕" aria-label="Permalink to &quot;五、银行基层运营：宏观数据失真的微观根源〔175〕&quot;">​</a></h2><p><strong>存款冲量（揽储）</strong>：揽存三招——&quot;一揽存款进账，二卡客户转出，三把存量放进蒸笼膨胀&quot;：先忽悠存款进来，客户要转账时设置审批拖延到月初。月末月初对公存款大起大落即冲量痕迹。同业绕道：找村镇银行、农信社揽同业存款，因对公对私考核远严于同业。派生存款制造：让贷款企业&quot;借贷款存储蓄&quot;（个人名义入储蓄科目）、以存单作保证金开承兑汇票、急需现金时转到关系公司去他行贴现——一笔贷款派生出存款+中间业务收入两份业绩；季末任务未完再如法炮制一遍。</p><p><strong>利润虚增三法</strong>：① 服务费提前入帐——数年期贷款的服务费一次性收取且集中在季末年末关键时点；② 预收入帐——对未获审批、未提款的客户&quot;先按收益率底线讹钱入帐完成指标&quot;，即对根本没提供服务的客户收费；③ 假入帐——季末向客户借入巨额资金充作中间业务收入，考核时段过后冲帐。再叠加贷款风险分类人为上调、少提拨备。&quot;一个分号年度利润中虚增水分达亿&quot;。</p><p><strong>贷款的真实价格</strong>：名义基准利率之外，按基准上浮 20%–35% 收财务顾问费、资金监管费，再加审计费、抵押评估费（银行与评估公司分成）、保险代理费、担保费——一般企业实际支出&quot;至少是基准利率上浮 40%–50%&quot;；开发贷与平台贷还会一次性预收全部年份的上浮费。隐形成本：协助完成储蓄任务的息差、开票贴现费、被摊销买入基金的手续费与亏损。<strong>知识点</strong>：这解释了&quot;融资贵&quot;的制度来源——清理收费只会把费用变回利息（&quot;从清理乱收费解决融资难，本来就是个世纪大笑话&quot;）。</p><p><strong>贷款三查名存实亡</strong>：借壳贷款——不符合产业政策/无合格主体的借款人，与壳公司、银行经手人三方勾结，&quot;一方借壳三方得益&quot;；内外勾结伪造销售报表；抵押品高估。审计验证法〔175〕：同一支行内，查&quot;已放贷未收费企业（甲）&quot;与&quot;已收费未放贷企业（乙）&quot;之间的资金对倒，&quot;甲乙还账交易额与乙的中间业务实收额之和≈乙的审批测算综合收益&quot;即坐实。</p><p><strong>影子银行的具体玩法（理财产品）</strong>：银行理财募集时间设计在月底季末——&quot;停在银行账面上&quot;充当存款冲份额，月初经信托通道转给融资方；超短期理财=变相突破利率管制提价；银行再用信贷投放&quot;兜底理财产品本金的兑付&quot;——表外风险实际由表内垫底。经济上行期违约少，&quot;退潮期千万别碰：你惦记别人的利息，别人惦记你的本金&quot;〔175/43〕。P2P 的钱一部分被挥霍，大部分&quot;反正要通胀嘛，18% 利息算毛&quot;加杠杆接盘，套死后跑路〔43〕。</p><p><strong>&quot;变通&quot;的成本科目（识别假账的样本库）</strong>〔175〕：车改后仍报海量汽油费（&quot;公家马私家骡同槽吃草&quot;，鲍鱼海参在发票上叫骡马草料）；打印纸、办公桌采购天量（&quot;几十人单位一年报销几百张办公桌&quot;）；节前季初大卖场巨额发票；购物卡、储值卡、酒店会所记账单（&quot;小金库的与时俱进&quot;）。变通的规律性方向：限制性科目向非限制性科目变通、违法向违规变通、违规向正常经营变通。<strong>宏观含义</strong>：当造假有稳定的方向性规律时，数据失真就不是随机噪声而是系统性偏差，&quot;不是一笔糊涂帐而是一概糊涂帐&quot;。</p><p><strong>帐外经营的审计钩子</strong>〔175〕：预收了申贷企业的巨额服务费而贷款未获批，会计制度又不许冲回，于是&quot;套取后来自投罗网的申贷企业去还前面未能贷款企业的服务费&quot;——用新苦主的钱退旧苦主，庞氏结构在支行层面重现。识别：查同一实际控制人下不同贷款主体间的资金交易与审批综合收益的印证关系。</p><p><strong>宏观推论</strong>：公司信贷数据最先失真（借壳、变通、分类上调），&quot;以公司贷款数据为依据的研究没有太大价值&quot;；个人贷款数据相对真实（后来也被经营贷消费贷入楼污染）〔175〕。读宏观数据前先问：这个数字的微观生成机制里有多少冲量与变通。</p><h2 id="六、宏观研判操作性清单-指标-区间-出处" tabindex="-1">六、宏观研判操作性清单（指标+区间+出处） <a class="header-anchor" href="#六、宏观研判操作性清单-指标-区间-出处" aria-label="Permalink to &quot;六、宏观研判操作性清单（指标+区间+出处）&quot;">​</a></h2><ol><li><strong>M2 增速</strong>：常态区间 12%–14%（2008–2016）；跌破 11% 是政策真转向的标志——2016 年 8 月 M2 增速 10.2% 历史新低，&quot;实际上已经标志着货币政策开始真正转向，按市场传导年底前反应出来&quot;〔43〕。M1-M2 剪刀差异常（2016 年）＝资金活化投机，警戒〔20〕。</li><li><strong>外汇储备</strong>：峰值约 4 万亿（2014）；流失 1 万亿至 3.2 万亿进入警戒〔43〕；3 万亿整数关是心理与政策双重底线（2017 年初跌破后紧缩加码）〔43〕。</li><li><strong>外汇占款</strong>：占基础货币八成（23.5/29 万亿，2016）〔43〕；月降 1000 亿美元×乘数≈5000 亿缺口，连续下降=基础货币流失、降准=对冲而非放水。<strong>这是判断&quot;放水还是救火&quot;的第一指标。</strong></li><li><strong>信贷结构</strong>：新增贷款中房贷占比——超过 50% 即庞氏信号（2016 年 7 月 102%）〔43〕。</li><li><strong>CPI/PPI 同低位</strong>＝放水失效确认〔43〕；&quot;连放水都拉不起物价，是货币政策失效的前兆&quot;。</li><li><strong>居民杠杆率</strong>：家庭债务/GDP，2017 年 49.1%（十年+30 个百分点，&quot;没有其他国家私人债务负担增长如此之快&quot;）〔84〕——50% 上下为消费承压区，快速上行期警惕。</li><li><strong>存款分布</strong>：约 50 万亿住户存款中 50 多万亿集中在 1 千万人手里，10 亿人人均约 8000 元〔84〕——内需天花板的微观注脚。</li><li><strong>租金售价比</strong>：&quot;租金能覆盖按揭的房子，市场上不存在，有就说明房价定低了会被中介自己收走&quot;〔23〕——全市场租金回报远低于按揭利率＝纯金融属性定价，跌时无使用价值托底。</li><li><strong>本地楼市测试法（可操作）</strong>：找一件真要卖的房，&quot;按今年价格挂低两成，成交不了说明当地繁荣是虚假的；按去年价格也卖不掉，说明已完&quot;〔43〕；商铺价格是住宅的领先指标（先破）〔43〕。</li><li><strong>猪肉价格</strong>：通胀体感与货币压力的代理变量，&quot;炒股票研究 K 线图还不如关注猪肉的价格走势&quot;；猪肉见顶≈调控收紧窗口〔16〕。</li><li><strong>美元周期</strong>：识别&quot;从 0 利率回归正常&quot;与&quot;过热加息&quot;的区别——前者为了储备降息弹药，&quot;这一波加息速度一定会让你瞠目结舌&quot;（2022–2023 应验）〔43〕；黄金与美元反向〔43〕。</li><li><strong>M2 与顺差的对接</strong>（七剑）：顺差收窄+M2 天量=汇率压力源，&quot;特朗普不让 M2 跟顺差对接，中国也只能紧缩&quot;〔20〕。</li><li><strong>房贷利率与基准的利差</strong>（七剑，2018）：首套房贷利率 5.5%、&quot;年底到 6% 可以预期&quot;——房贷利率与基准的利差扩大是信贷紧缩的零售端读数，先于基准加息出现〔20〕。</li><li><strong>机构仓位</strong>（黄汉升 2014.10）：三季报披露后&quot;股票型基金平均仓位 83.8%→88.3%，219 只基金九成以上&quot;——正规军子弹打光＝增量衰竭，对应&quot;四季度鸡肋行情&quot;；该指标与散户情绪反向使用：基金满仓+基金发行火爆=顶部区，基金低仓+无人问津=底部区〔92〕。</li><li><strong>政策文本的微观读法</strong>（曼因斯坦示范）：发改委说&quot;进一步引导利率下行空间依然很大&quot;＝下游快死了催放水；央行说&quot;流动性充裕可以支持各个市场&quot;并把逆回购从 7 天换成 14 天＝提高资金成本、实为收紧；&quot;逆回购、MLF 用得越多，越说明央行不敢放水——这些短期工具不能派生货币，到期还得置换&quot;〔43〕。<strong>读政策看工具选择，不看措辞。</strong></li></ol><h2 id="七、2021–2026-的验证与失效点" tabindex="-1">七、2021–2026 的验证与失效点 <a class="header-anchor" href="#七、2021–2026-的验证与失效点" aria-label="Permalink to &quot;七、2021–2026 的验证与失效点&quot;">​</a></h2><p><strong>验证清单</strong>：① 通缩叙事——2023 年后 CPI 贴零、PPI 负增长，&quot;钱快没了&quot;成立〔43〕；② 债务路径——低息置换+展期+居民承接，与预测的第三条路径一致〔43〕；③ P2P 2020 年清零、2022 年理财破净，&quot;跟 P2P 不会有太大区别&quot;应验〔43〕；④ 房企暴雷、二手房流动性陷阱（挂低两成卖不掉成为普遍现实）〔20/43〕；⑤ 土地财政坍塌——王海滨 2009 年画出的&quot;财政→地产→加税→实体&quot;链条在 2021 年后进入反向运转〔23〕；⑥ 金融风险向居民部门转移（黄汉升 2014.11）——居民杠杆翻倍完成承接〔92〕；⑦ 注册制 2023 年全面落地——kulese&quot;跌到底换制度&quot;的剧本迟到八年兑现〔15〕。</p><p><strong>失效清单</strong>：① <strong>时点集体早 3 年</strong>（机制见第四节），最贵的教训是照做会在 2018–2020 离场，错过最后一轮顶；② <strong>&quot;M2 被动紧缩&quot;错了</strong>——2020 年疫情大放水、2021 年后是低利率+债务置换，不是七剑设想的&quot;印钞机被关闭&quot;〔20〕，说明汇率约束可以让位于增长目标；③ <strong>&quot;人民币贬值窗口关闭&quot;错了</strong>——2018–2019 贸易战期间贬值至 7 附近，有管理贬值是常态而非一次性选择〔43〕；④ <strong>制度性大杀器全部迟到</strong>：房产税至今未立法、宅基地未入市、人民币国际化份额仍低——高估政策速度是这批帖子的系统性偏差；⑤ 蓄水池理论的<strong>人口盲点</strong>：帖内默认城镇化与居民购买力会持续填充池子，2021 年后出生人口与人口总量见顶，池子的分母端塌了——这是框架本身没有的变量（2021 年后事实，非帖内观点）。</p><p><strong>使用须知</strong>：这套框架是&quot;货币-债务&quot;单因子强框架，擅长解释资产价格与政策腾挪，弱于供给面——产业升级、技术代差〔176〕与人口结构需另补维度；帖内&quot;共济会/中美默契&quot;类阴谋论成分（曼因斯坦自认&quot;不是阴谋论者，但蛛丝马迹太匪夷所思&quot;）应剥离，保留其央行资产负债表与明斯基的可验证部分。三套独立方法（读文件倒推布局〔16〕、拆央行报表〔43〕、利益流向分析〔15/23/175〕）在 2015、2016 两个节点交叉验证过——<strong>方法互证，胜过任何单一预测</strong>。</p>',50)])])}const h=o(n,[["render",s]]);export{i as __pageData,h as default};
